#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.19105228, -0.15873447000000002, -0.16286387], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.049199770000000004, 'zmax': 0.049199770000000004, 'profiles': [{'outer': [[-0.15516284, -0.043450219999999984], [-0.16063434, -0.012932609999999983], [-0.15981507, 0.020774260000000017], [-0.15308539, 0.05047260000000002], [-0.1392164, 0.08122426000000002], [-0.11931996, 0.10837704000000001], [-0.09415683999999999, 0.13081902], [-0.06492664, 0.14755541000000003], [-0.049501231818243084, 0.15179530321562043], [-0.04991654999999999, 0.15308544000000002], [-0.04061205, 0.15589437], [-0.025923790000000002, 0.15911290000000003], [-0.01685822417357823, 0.1587595224200621], [-0.016999669999999995, 0.16010770000000002], [-0.007373309999999994, 0.16092697], [0.007666050000000008, 0.16104400000000002], [0.01647692074849093, 0.1588078507231908], [0.016619440000000013, 0.1601662], [0.026245800000000014, 0.1589373], [0.04102179, 0.15592360000000002], [0.049103510119035416, 0.15194897443800987], [0.04950703000000001, 0.15320247], [0.058694490000000016, 0.15001318000000002], [0.07244642000000001, 0.14398572], [0.07958967741021832, 0.13837314844695062], [0.08025871000000001, 0.13956752000000003], [0.10088662000000001, 0.12575707000000003], [0.12429414000000003, 0.10264212000000002], [0.14334206000000002, 0.07388008000000001], [0.15525065000000002, 0.043596520000000014], [0.15605501323584683, 0.0334498741610565], [0.15732805000000002, 0.03373609000000001], [0.15776692, 0.03212683000000002], [0.16075138000000003, 0.012991140000000012], [0.15964912617084334, 0.0002340200000000292], [0.16098545, 0.0002340200000000292], [0.16031251, -0.017526459999999994], [0.15320245000000002, -0.050443319999999986], [0.13918719999999998, -0.08116572999999999], [0.11718402000000003, -0.11074700999999998], [0.09424464000000002, -0.13070196], [0.08850978000000001, -0.13485679], [0.08011570683815361, -0.13815188428074618], [0.08072677, -0.13918718999999996], [0.07224153, -0.14401497999999996], [0.04274800000000001, -0.15525061], [0.026011630000000008, -0.15914211], [-0.0076952599999999816, -0.16098543999999998], [-0.016509002883433505, -0.15869995205606555], [-0.016648649999999987, -0.16007841], [-0.04096324999999999, -0.15595281], [-0.049126188006477015, -0.15184697980366457], [-0.04956553999999999, -0.15320242], [-0.051057759999999994, -0.15273428], [-0.07250493, -0.14401495999999997], [-0.10082806999999999, -0.12566927], [-0.10754079121061208, -0.1176532474658586], [-0.11299999999999999, -0.11466770999999998], [-0.12476229, -0.10205689000000001], [-0.14325425, -0.07382151999999997]], 'holes': [[[-0.055811403799900815, -0.039708867085368645], [-0.05225735999999999, -0.030137199999999975], [-0.05243291, -0.021651969999999993], [-0.05483218999999999, -0.014658959999999971], [-0.059835559999999996, -0.00790001999999998], [-0.0689397312915515, -0.0021489016445366124], [-0.06928635, -0.006056669999999986], [-0.06302485, -0.029347179999999973]], [[-0.021681210000000006, 0.05249146000000002], [-0.014688210000000007, 0.05489074000000002], [-0.007812249999999993, 0.05989410000000002], [-0.0023916836395416682, 0.06859551787857458], [-0.01802376, 0.06720896000000001], [-0.04076472508466974, 0.05619821818160522], [-0.03016647, 0.05231589000000002]], [[-0.047585082723822836, -0.050324167523796766], [-0.029376479999999983, -0.06305408999999998], [-0.011153008874969332, -0.06790758499101893], [-0.015624539999999992, -0.058226289999999986], [-0.02168123999999999, -0.05240365999999999], [-0.028352409999999995, -0.04918509999999998], [-0.03672059, -0.04792692999999998]], [[-0.05243289999999999, 0.021798330000000005], [-0.049097329999999995, 0.028469470000000024], [-0.04783915999999999, 0.03683768000000001], [-0.05014434729152581, 0.046786368498366315], [-0.05696810999999999, 0.039939160000000015], [-0.06715041, 0.018023850000000008], [-0.0677494163090276, 0.0112706718186534], [-0.058343309999999995, 0.015624580000000027]], [[0.05249148000000001, 0.02179830000000002], [0.05480298, 0.014688240000000019], [0.05983558, 0.007929290000000006], [0.06892489645212703, 0.002235272857725334], [0.06925709, 0.006085950000000007], [0.06305414000000001, 0.029493500000000006], [0.05582905395591742, 0.03976716322920072], [0.05228665000000002, 0.030166480000000023]], [[0.021769060000000007, 0.052491440000000014], [0.028410950000000018, 0.04921439000000001], [0.036779160000000005, 0.047956230000000016], [0.047492271827999775, 0.050404944263887384], [0.029464309999999994, 0.06308336000000002], [0.01125536760765219, 0.06795425807984934], [0.015683080000000016, 0.05834334000000002]], [[0.007900039999999997, -0.05983554999999999], [0.0023843232715851396, -0.06852637007189809], [0.017994549999999998, -0.06717967999999999], [0.04072143802955616, -0.05612731344665636], [0.03013724000000001, -0.05228662999999997], [0.021769029999999995, -0.05240365999999999], [0.014658980000000016, -0.05480292999999997]], [[0.06776274657516007, -0.011235982065158691], [0.05834336000000001, -0.015566039999999975], [0.05249147000000001, -0.021651999999999977], [0.04918515000000001, -0.028293889999999988], [0.04792699, -0.03669133999999999], [0.050141458498816925, -0.04670730951579808], [0.056968149999999995, -0.03988062999999997], [0.06717969000000001, -0.017994579999999982]]]}], 'simplify_tolerance': 0.0009156347696231197, 'sketch_entity_count': 138}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
